'use strict';
const shareToken=location.hash.slice(1),shareGate=document.querySelector('#share-gate'),shareMessage=document.querySelector('#share-message'),shareForm=document.querySelector('#share-password-form'),shareFrame=document.querySelector('#shared-report'),sharePrint=document.querySelector('#share-print');let shareExpires=0;
function closeSharedReport(message){shareFrame.hidden=true;shareFrame.removeAttribute('srcdoc');shareGate.hidden=false;shareMessage.textContent=message;shareForm.hidden=true;sharePrint.hidden=true;document.querySelector('#share-password').value='';}
async function fetchSharedReport(password){if(!/^[a-f0-9]{64}$/.test(shareToken))return closeSharedReport('Liên kết không hợp lệ. Hãy kiểm tra lại link được chia sẻ.');try{const response=await fetch('/api/report-share/'+shareToken,{method:password===undefined?'GET':'POST',headers:password===undefined?{}:{'Content-Type':'application/json'},body:password===undefined?undefined:JSON.stringify({password}),credentials:'omit',cache:'no-store',referrerPolicy:'no-referrer'});const data=await response.json();if(!response.ok){if(response.status===401){shareMessage.textContent=data.error;return;}return closeSharedReport(data.error||'Chưa mở được báo cáo.');}shareExpires=data.expires;document.querySelector('#share-expiry').textContent='Hết hạn: '+new Date(data.expires).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'})+' (VN)';if(data.locked){shareGate.hidden=false;shareForm.hidden=false;shareMessage.textContent='Nhập mật khẩu do người chia sẻ cung cấp để xem báo cáo.';return;}shareGate.hidden=true;shareForm.hidden=true;shareFrame.srcdoc=data.html;shareFrame.hidden=false;shareFrame.onload=()=>{if(Date.now()<shareExpires)sharePrint.hidden=false;};document.title=data.title||'Báo cáo tuần · Zen Studio';}catch{shareGate.hidden=false;shareMessage.textContent='Chưa kết nối được máy chủ. Tải lại trang để thử lại.';}}
shareForm.onsubmit=async e=>{e.preventDefault();const button=shareForm.querySelector('button');button.disabled=true;try{await fetchSharedReport(document.querySelector('#share-password').value);}finally{document.querySelector('#share-password').value='';button.disabled=false;}};
sharePrint.onclick=()=>{if(Date.now()>=shareExpires)return closeSharedReport('Liên kết đã hết hạn.');shareFrame.contentWindow.focus();shareFrame.contentWindow.print();};setInterval(()=>{if(shareExpires&&Date.now()>=shareExpires)closeSharedReport('Liên kết đã hết hạn. Liên hệ người chia sẻ để nhận link mới.');},1000);fetchSharedReport();
